                'size': entry['size'],
                'lang': entry.get('lang', '?'),
                'bloat': entry.get('bloat', False),
                'deps': [],
                'dependents': []
            }

    # Compact output: remove entries with no deps and no dependents? Keep only if bloat false? Let's keep all for completeness.
    # Write graph
    print(f"[✓] {import_count} dependencies mapped. Writing graph to {GRAPH_OUT}")
