"""1337 MAPPER GRAPH v1.2 – path‑safe, multi‑lang resolver."""
import json, re, os, subprocess, sys
from pathlib import Path
from collections import defaultdict

HOME = Path.home()
MAP_FILES = ['map_py.jsonl','map_js.jsonl','map_sh.jsonl','map_json.jsonl',
             'map_md.jsonl','map_other.jsonl','central_index.jsonl']
GRAPH_OUT = HOME / 'file_graph.json'

IMPORT_RE = {
    'python': re.compile(r'^(?:from\s+(\S+)\s+import\s+.*|import\s+(\S+))', re.MULTILINE),
    'javascript': re.compile(r'(?:require\s*\(\s*[\'"](.+?)[\'"]\s*\)|import\s+.*\s+from\s*[\'"](.+?)[\'"]|from\s+[\'"](.+?)[\'"]\s*import)', re.MULTILINE),
    'bash': re.compile(r'(?:source\s+(\S+)|\.\s+(\S+))')
}

def resolve_import_target(file_path: Path, import_spec: str) -> Path:
    """Relative import resolution (dots only)."""
    if import_spec.startswith('.'):
        base = file_path.parent
        parts = import_spec.split('.')
        up = 0
        for p in parts:
            if p == '':
                up += 1
            else:
                break
        base = base.parents[up] if up else base
        module_path = '/'.join(parts[up:])
        for ext in ('', '.py', '.js', '.sh'):
            candidate = base / (module_path + ext if ext else module_path)
            if candidate.exists():
                return candidate
        candidate = base / module_path / '__init__.py'
        if candidate.exists():
            return candidate
    return None

def extract_imports(file_path: Path, lang: str) -> list:
    try:
        content = file_path.read_text(errors='ignore')
    except:
        return []
    imports = set()
    if lang == 'python':
        try:
            cmd = ['sg', '--pattern', 'import_statement', '--lang', 'python',
                   '--json', str(file_path)]
            res = subprocess.run(cmd, capture_output=True, text=True, timeout=5)
            if res.returncode == 0 and res.stdout.strip():
                for line in res.stdout.splitlines():
                    try: match = json.loads(line)
                    except: continue
                    node = match.get('text','')
                    for m in re.finditer(r'(?:from\s+(\S+)\s+import|import\s+(\S+))', node):
                        imp = m.group(1) or m.group(2)
                        if imp: imports.add(imp.strip('"\''))
                return list(imports)
        except: pass
        for m in IMPORT_RE['python'].finditer(content):
            imp = m.group(1) or m.group(2)
            if imp: imports.add(imp.strip('"\''))
    elif lang in ('javascript','bash'):
        for m in IMPORT_RE[lang].finditer(content):
            imp = next((g for g in m.groups() if g), None)
            if imp: imports.add(imp.strip('"\''))
    return list(imports)

def resolve_import_to_file(import_spec, current_file: Path, file_set: set) -> Path:
    """Resolve an import string (may be relative, absolute, bare) to a known file."""
    # Handle leading slash (absolute path) -> treat as relative to HOME
    clean = import_spec.lstrip('/')
